package com.sentinel.audit.service;

import com.sentinel.audit.model.Finding;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Reconhece arquivo gerado pelo cabeçalho ("Generated file, DO NOT EDIT", "@generated", "Code generated ..."), que o
 * nome da pasta sozinho não revela. Cliente gerado a partir de especificação gera milhares de achados de estilo que
 * ninguém corrige à mão: o conserto é no gerador.
 */
final class GeneratedFiles {

    /** Só o início do arquivo conta: o aviso de geração vem sempre no cabeçalho. */
    static final int HEADER_BYTES = 1024;

    private GeneratedFiles() {}

    /** Caminhos (relativos, como nos achados) dos arquivos com cabeçalho de código gerado. */
    static Set<String> detect(Path root, List<Finding> findings) {
        Set<String> generated = new HashSet<>();
        Set<String> seen = new HashSet<>();
        if (root == null) {
            return generated;
        }
        Path base = root.toAbsolutePath().normalize();
        for (Finding f : findings) {
            String rel = f.getFilePath();
            if (rel == null || rel.isBlank() || !seen.add(rel)) {
                continue;
            }
            Path file = base.resolve(rel).normalize();
            if (!file.startsWith(base) || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
                continue;
            }
            if (hasGeneratedHeader(readHeader(file))) {
                generated.add(rel);
            }
        }
        return generated;
    }

    static boolean hasGeneratedHeader(String header) {
        if (header == null || header.isEmpty()) {
            return false;
        }
        String h = header.toLowerCase(Locale.ROOT);
        if (h.contains("@generated") || (h.contains("code generated") && h.contains("do not edit"))) {
            return true;
        }
        return saysGenerated(h) && saysDoNotEdit(h);
    }

    private static boolean saysGenerated(String h) {
        return h.contains("generated file") || h.contains("auto-generated") || h.contains("autogenerated")
                || h.contains("automatically generated");
    }

    private static boolean saysDoNotEdit(String h) {
        return h.contains("do not edit") || h.contains("do not modify") || h.contains("don't edit");
    }

    private static String readHeader(Path file) {
        try (InputStream in = Files.newInputStream(file)) {
            return new String(in.readNBytes(HEADER_BYTES), StandardCharsets.UTF_8);
        } catch (IOException e) {
            return "";
        }
    }
}
